const items = $input.all();

const processed = items.map(item => {
  const data = item.json;
  let source = "Tech News";
  const link = data.link || "";
  if (link.includes("techcrunch.com")) source = "TechCrunch";
  else if (link.includes("ycombinator.com") || link.includes("news.ycombinator")) source = "Hacker News";
  else if (link.includes("theverge.com")) source = "The Verge";
  else if (link.includes("dev.to")) source = "Dev.to";

  return {
    title: data.title || "No Title",
    link: link,
    description: data.contentSnippet || data.content || data.description || "",
    pubDate: data.pubDate || data.isoDate || new Date().toISOString(),
    source: source
  };
});

// Remove duplicates based on URL or Title
const unique = [];
const seen = new Set();
for (const item of processed) {
  const key = item.link || item.title;
  if (!seen.has(key)) {
    seen.add(key);
    unique.push(item);
  }
}

// Sort by date (newest first)
unique.sort((a, b) => new Date(b.pubDate) - new Date(a.pubDate));

// Limit to top 12 items
const limited = unique.slice(0, 12);

return limited.map(item => ({ json: item }));

